def transforms(shape, refl=True):
 shapes=set()
 for flip in ([1,-1] if refl else [1]):
  for rot in range(4):
   pts=shape.copy(); pts[:,1]*=flip
   for _ in range(rot): pts=np.stack([pts[:,1],-pts[:,0]],axis=1)
   pts-=pts.min(axis=0)
   shapes.add(tuple(sorted(map(tuple,pts.tolist()))))
 return [np.array(x) for x in shapes]
